// The injected runtime and a plugin's bundled helper share the binding.
const placementKey = Symbol.for('webview-native-ui-engine.projection-placement');
export const bindProjectionPlacement = (element, measure, invalidate = () => { }) => {
    const host = element;
    const state = { projected: false, measure, invalidate };
    host[placementKey] = state;
    return {
        get projected() {
            return host[placementKey] === state && state.projected;
        },
        dispose() {
            if (host[placementKey] === state)
                delete host[placementKey];
            state.projected = false;
        },
    };
};
export const projectionPlacement = (element) => element?.[placementKey];
